fun hashTag(key: String): String {
    val open = key.indexOf('{')
    if (open < 0) return key
    val close = key.indexOf('}', open + 1)
    if (close < 0 || close == open + 1) return key       // no }, or {} with nothing inside
    return key.substring(open + 1, close)
}

fun slot(key: String): Int = crc16(hashTag(key).toByteArray(Charsets.UTF_8)) % 16_384

// {merchant:7}:payments, merchant:7 and x{merchant:7}y all hash "merchant:7": slot 10890.
// {merchant:7 has no closing brace, so the whole key is hashed: slot 2924.

